-- ========================================================
-- 1. RETORNAR TABELAS PARA O SCHEMA PUBLIC
-- ========================================================
DO 
BEGIN
  -- Mover tabelas de volta para public se estiverem em dia_a_dia_nordeste
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'dia_a_dia_nordeste' AND table_name = 'noticias') THEN
    ALTER TABLE dia_a_dia_nordeste.noticias SET SCHEMA public;
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'dia_a_dia_nordeste' AND table_name = 'categorias') THEN
    ALTER TABLE dia_a_dia_nordeste.categorias SET SCHEMA public;
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'dia_a_dia_nordeste' AND table_name = 'autores') THEN
    ALTER TABLE dia_a_dia_nordeste.autores SET SCHEMA public;
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'dia_a_dia_nordeste' AND table_name = 'banners_ads') THEN
    ALTER TABLE dia_a_dia_nordeste.banners_ads SET SCHEMA public;
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'dia_a_dia_nordeste' AND table_name = 'galeria_midias') THEN
    ALTER TABLE dia_a_dia_nordeste.galeria_midias SET SCHEMA public;
  END IF;
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'dia_a_dia_nordeste' AND table_name = 'web_stories') THEN
    ALTER TABLE dia_a_dia_nordeste.web_stories SET SCHEMA public;
  END IF;
END ;

-- Notificar o PostgREST para recarregar o cache de tabelas
NOTIFY pgrst, 'reload config';
NOTIFY pgrst, 'reload schema';

